import { type Spec, action, page, query, route } from "@wasp.sh/spec";
import {
  createTask,
  deleteCompletedTasks,
  updateTaskStatus,
} from "./actions" with { type: "ref" };
import { getTasks } from "./queries" with { type: "ref" };
import { TasksPage } from "./TasksPage" with { type: "ref" };

export const tasksSpec: Spec = [
  route("TasksRoute", "/", page(TasksPage, { authRequired: true })),
  query(getTasks, { entities: ["Task", "Tag"] }),
  action(createTask, { entities: ["Task"] }),
  action(updateTaskStatus, { entities: ["Task"] }),
  action(deleteCompletedTasks, { entities: ["Task"] }),
];

import { type Tag, type Task } from "wasp/entities";
import { HttpError } from "wasp/server";
import {
  DeleteCompletedTasks,
  type CreateTask,
  type UpdateTaskStatus,
} from "wasp/server/operations";

type CreateTaskArgs = Pick<Task, "description"> & {
  tagIds: Tag["id"][];
};

export const createTask: CreateTask<CreateTaskArgs, Task> = async (
  { description, tagIds },
  context,
) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  return context.entities.Task.create({
    data: {
      description,
      isDone: false,
      user: {
        connect: {
          id: context.user.id,
        },
      },
      tags: {
        connect: tagIds.map((tag) => ({
          id: tag,
        })),
      },
    },
  });
};

type UpdateTaskStatusArgs = Pick<Task, "id" | "isDone">;

export const updateTaskStatus: UpdateTaskStatus<UpdateTaskStatusArgs> = async (
  { id, isDone },
  context,
) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  return context.entities.Task.update({
    where: {
      id,
    },
    data: { isDone },
  });
};

export const deleteCompletedTasks: DeleteCompletedTasks = async (
  _args,
  context,
) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  return context.entities.Task.deleteMany({
    where: {
      userId: context.user.id,
      isDone: true,
    },
  });
};

import { Tag, Task } from "wasp/entities";
import { HttpError } from "wasp/server";
import { type GetTasks } from "wasp/server/operations";

export type TaskWithTags = Task & { tags: Tag[] };

export const getTasks: GetTasks<void, TaskWithTags[]> = (_args, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  return context.entities.Task.findMany({
    where: { user: { id: context.user.id } },
    orderBy: { createdAt: "desc" },
    include: {
      tags: {
        orderBy: { name: "asc" },
      },
    },
  });
};

import { type AuthUser } from "wasp/auth";
import { CreateTaskForm } from "./components/CreateTaskForm";
import { TaskList } from "./components/TaskList";

export const TasksPage = ({ user }: { user: AuthUser }) => {
  return (
    <div className="flex flex-col items-center gap-8 px-8 py-12">
      <h1 className="text-4xl font-bold">{`${user.username}'s tasks`}</h1>
      <div className="flex w-full flex-col items-center gap-6">
        <section className="card flex w-full max-w-3xl flex-col gap-6 p-4 lg:p-6">
          <CreateTaskForm />
        </section>
        <section className="card flex w-full max-w-3xl flex-col gap-6 p-4 lg:p-6">
          <TaskList />
        </section>
      </div>
    </div>
  );
};

