datasource db {
  provider = "sqlite"
  url      = env("DATABASE_URL")
}

generator client {
  provider = "prisma-client-js"
}

model User {
  id       Int    @id @default(autoincrement())
  username String @unique

  messages     Message[]
  readReceipts ReadReceipt[]
}

model Channel {
  id   Int    @id @default(autoincrement())
  name String @unique

  messages     Message[]
  readReceipts ReadReceipt[]
}

model Message {
  id        Int      @id @default(autoincrement())
  content   String
  createdAt DateTime @default(now())

  senderId  Int
  sender    User    @relation(fields: [senderId], references: [id])
  channelId Int
  channel   Channel @relation(fields: [channelId], references: [id])

  readReceipts ReadReceipt[]
}

model ReadReceipt {
  id                Int @id @default(autoincrement())
  lastReadMessageId Int
  lastReadMessage   Message @relation(fields: [lastReadMessageId], references: [id])

  userId    Int
  user      User    @relation(fields: [userId], references: [id])
  channelId Int
  channel   Channel @relation(fields: [channelId], references: [id])

  @@unique([userId, channelId])
}

import { app, page, route, query, action } from "@wasp.sh/spec";
import { App } from "./src/App" with { type: "ref" };
import { LoginPage } from "./src/auth/email/LoginPage" with { type: "ref" };
import { SignupPage } from "./src/auth/email/SignupPage" with { type: "ref" };
import { MainPage } from "./src/pages/MainPage" with { type: "ref" };
import { ChannelPage } from "./src/pages/ChannelPage" with { type: "ref" };
import { getChannels } from "./src/queries" with { type: "ref" };
import { getChannel } from "./src/queries" with { type: "ref" };
import { getChannelMessages } from "./src/queries" with { type: "ref" };
import { createChannel } from "./src/actions" with { type: "ref" };
import { createMessage } from "./src/actions" with { type: "ref" };
import { markAsRead } from "./src/actions" with { type: "ref" };
import { webSocketFn } from "./src/webSocket" with { type: "ref" };
import { seedDevData } from "./src/seed" with { type: "ref" };
import { userSignupFields } from "./src/auth/email/userSignupFields" with { type: "ref" };

export default app({
  name: "chatApp",
  title: "Chat App",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {
        userSignupFields,
      },
    },
    onAuthFailedRedirectTo: "/login",
  },
  webSocket: {
    fn: webSocketFn,
    autoConnect: true,
  },
  db: {
    seeds: [seedDevData],
  },
  client: {
    rootComponent: App,
  },
  spec: [
    route("MainRoute", "/", page(MainPage, { authRequired: true })),
    route("ChannelRoute", "/channel/:id", page(ChannelPage, { authRequired: true })),
    route("LoginRoute", "/login", page(LoginPage)),
    route("SignupRoute", "/signup", page(SignupPage)),
    query(getChannels, { entities: ["Channel"] }),
    query(getChannel, { entities: ["Channel"] }),
    query(getChannelMessages, { entities: ["Message", "ReadReceipt", "User"] }),
    action(createChannel, { entities: ["Channel"] }),
    action(createMessage, { entities: ["Message", "ReadReceipt"] }),
    action(markAsRead, { entities: ["ReadReceipt", "Message"] }),
  ],
});

import { HttpError } from "wasp/server";
import {
  type GetChannels,
  type GetChannel,
  type GetChannelMessages,
} from "wasp/server/operations";
import type { Channel, Message, ReadReceipt, User } from "wasp/entities";

export const getChannels: GetChannels<void, Channel[]> = async (
  _args,
  context,
) => {
  if (!context.user) {
    throw new HttpError(401);
  }
  return context.entities.Channel.findMany({
    orderBy: { name: "asc" },
  });
};

export const getChannel: GetChannel<{ id: number }, Channel | null> = async (
  { id },
  context,
) => {
  if (!context.user) {
    throw new HttpError(401);
  }
  return context.entities.Channel.findUnique({
    where: { id },
  });
};

export type MessageWithSender = Message & {
  sender: User;
  readReceipts: (ReadReceipt & { user: User })[];
};

export const getChannelMessages: GetChannelMessages<
  { channelId: number },
  MessageWithSender[]
> = async ({ channelId }, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }
  return context.entities.Message.findMany({
    where: { channelId },
    orderBy: { createdAt: "asc" },
    include: {
      sender: true,
      readReceipts: {
        include: {
          user: true,
        },
      },
    },
  });
};

import { HttpError } from "wasp/server";
import {
  type CreateChannel,
  type CreateMessage,
  type MarkAsRead,
} from "wasp/server/operations";
import type { Channel, Message, ReadReceipt } from "wasp/entities";
import { getSocketIO } from "./webSocket";

export const createChannel: CreateChannel<{ name: string }, Channel> = async (
  { name },
  context,
) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  const existing = await context.entities.Channel.findUnique({
    where: { name },
  });
  if (existing) {
    throw new HttpError(400, "Channel with this name already exists");
  }

  return context.entities.Channel.create({
    data: { name },
  });
};

export const createMessage: CreateMessage<
  { channelId: number; content: string },
  Message
> = async ({ channelId, content }, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  const message = await context.entities.Message.create({
    data: {
      content,
      senderId: context.user.id,
      channelId,
    },
  });

  // Upsert the sender's read receipt for this channel
  await context.entities.ReadReceipt.upsert({
    where: {
      userId_channelId: {
        userId: context.user.id,
        channelId,
      },
    },
    create: {
      userId: context.user.id,
      channelId,
      lastReadMessageId: message.id,
    },
    update: {
      lastReadMessageId: message.id,
    },
  });

  // Broadcast via WebSocket
  const io = getSocketIO();
  if (io) {
    io.to(`channel-${channelId}`).emit("messageCreated", {
      id: message.id,
      content: message.content,
      senderId: message.senderId,
      channelId: message.channelId,
      createdAt: message.createdAt,
      sender: {
        id: context.user.id,
        username: context.user.username,
      },
    });
  }

  return message;
};

export const markAsRead: MarkAsRead<
  { channelId: number; lastReadMessageId: number },
  ReadReceipt
> = async ({ channelId, lastReadMessageId }, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  const readReceipt = await context.entities.ReadReceipt.upsert({
    where: {
      userId_channelId: {
        userId: context.user.id,
        channelId,
      },
    },
    create: {
      userId: context.user.id,
      channelId,
      lastReadMessageId,
    },
    update: {
      lastReadMessageId,
    },
  });

  // Broadcast via WebSocket
  const io = getSocketIO();
  if (io) {
    io.to(`channel-${channelId}`).emit("readReceiptUpdated", {
      userId: context.user.id,
      username: context.user.username,
      lastReadMessageId,
    });
  }

  return readReceipt;
};

import type { Server as SocketIOServer } from "socket.io";
import type { WebSocketFn } from "wasp/server/webSocket";

let io: SocketIOServer | null = null;

export function getSocketIO(): SocketIOServer | null {
  return io;
}

// Track which users are active in which channels
// Map<channelId, Map<socketId, username>>
const channelUsers = new Map<number, Map<string, string>>();

function getActiveUsernames(channelId: number): string[] {
  const users = channelUsers.get(channelId);
  if (!users) return [];
  return Array.from(new Set(users.values()));
}

function broadcastActiveUsers(channelId: number) {
  if (!io) return;
  const usernames = getActiveUsernames(channelId);
  io.to(`channel-${channelId}`).emit("activeUsers", usernames);
}

export const webSocketFn: WebSocketFn = (socketIO, _context) => {
  io = socketIO;

  socketIO.on("connection", (socket) => {
    const user = socket.data.user;

    if (!user) {
      // Not authenticated, ignore
      return;
    }

    socket.on("joinChannel", ({ channelId }: { channelId: number }) => {
      const room = `channel-${channelId}`;
      socket.join(room);

      // Track active user
      if (!channelUsers.has(channelId)) {
        channelUsers.set(channelId, new Map());
      }
      channelUsers.get(channelId)!.set(socket.id, user.username);

      broadcastActiveUsers(channelId);
    });

    socket.on("leaveChannel", ({ channelId }: { channelId: number }) => {
      const room = `channel-${channelId}`;
      socket.leave(room);

      // Remove from active tracking
      const users = channelUsers.get(channelId);
      if (users) {
        users.delete(socket.id);
        if (users.size === 0) {
          channelUsers.delete(channelId);
        }
      }

      broadcastActiveUsers(channelId);
    });

    socket.on(
      "typing",
      ({ channelId, isTyping }: { channelId: number; isTyping: boolean }) => {
        const room = `channel-${channelId}`;
        socket.to(room).emit("typing", {
          username: user.username,
          isTyping,
        });
      },
    );

    socket.on("disconnect", () => {
      // Remove user from all channels they were in
      for (const [channelId, users] of channelUsers.entries()) {
        if (users.has(socket.id)) {
          users.delete(socket.id);
          if (users.size === 0) {
            channelUsers.delete(channelId);
          }
          broadcastActiveUsers(channelId);
        }
      }
    });
  });
};

import { sanitizeAndSerializeProviderData } from "wasp/server/auth";
import type { DbSeedFn } from "wasp/server/dbSeeds";

export const seedDevData: DbSeedFn = async (prisma) => {
  const { sanitizeAndSerializeProviderData } = await import(
    "wasp/server/auth"
  );

  const aliceData = await sanitizeAndSerializeProviderData(
    {
      username: {
        isPasswordHash: false,
        userData: "alice",
      },
      password: {
        isPasswordHash: false,
        userData: "password123",
      },
    },
    "username",
  );

  const alice = await prisma.user.upsert({
    where: { username: "alice" },
    create: {
      username: "alice",
      auth: {
        create: {
          identities: {
            create: {
              providerName: "username",
              providerUserId: "alice",
              providerData: aliceData,
            },
          },
        },
      },
    },
    update: {},
  });

  const bobData = await sanitizeAndSerializeProviderData(
    {
      username: {
        isPasswordHash: false,
        userData: "bob",
      },
      password: {
        isPasswordHash: false,
        userData: "password123",
      },
    },
    "username",
  );

  const bob = await prisma.user.upsert({
    where: { username: "bob" },
    create: {
      username: "bob",
      auth: {
        create: {
          identities: {
            create: {
              providerName: "username",
              providerUserId: "bob",
              providerData: bobData,
            },
          },
        },
      },
    },
    update: {},
  });

  await prisma.channel.upsert({
    where: { name: "#general" },
    create: { name: "#general" },
    update: {},
  });

  await prisma.channel.upsert({
    where: { name: "#random" },
    create: { name: "#random" },
    update: {},
  });

  console.log("Seed data created: alice, bob, #general, #random");
};

import { type AuthUser } from "wasp/auth";
import { useQuery } from "wasp/client/operations";
import { getChannels } from "../queries";
import { createChannel } from "../actions";
import { logout } from "wasp/client/auth";
import { useState } from "react";

export const MainPage = ({ user }: { user: AuthUser }) => {
  const { data: channels, isLoading, refetch } = useQuery(getChannels);
  const [channelName, setChannelName] = useState("");
  const [error, setError] = useState("");

  const handleCreateChannel = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    try {
      await createChannel({ name: channelName });
      setChannelName("");
      refetch();
    } catch (err: unknown) {
      const message =
        err instanceof Error ? err.message : "Failed to create channel";
      setError(message);
    }
  };

  return (
    <div className="flex flex-col items-center gap-8 px-8 py-12">
      <h1 data-testid="main-title" className="text-4xl font-bold">
        Chat App
      </h1>

      <div className="card flex w-full max-w-3xl flex-col gap-4 p-6">
        <h2 className="text-xl font-semibold">Create Channel</h2>
        <form onSubmit={handleCreateChannel} className="flex gap-2">
          <input
            id="channel-name-input"
            data-testid="channel-name-input"
            type="text"
            value={channelName}
            onChange={(e) => setChannelName(e.target.value)}
            placeholder="Channel name (e.g. #general)"
            className="flex-1 rounded border border-neutral-300 px-3 py-2"
          />
          <button
            id="create-channel-btn"
            data-testid="create-channel-btn"
            type="submit"
            className="rounded bg-blue-600 px-4 py-2 text-white hover:bg-blue-700"
          >
            Create Channel
          </button>
        </form>
        {error && <p className="text-sm text-red-500">{error}</p>}
      </div>

      <div className="card flex w-full max-w-3xl flex-col gap-4 p-6">
        <h2 className="text-xl font-semibold">Channels</h2>
        {isLoading && <p>Loading channels...</p>}
        <div data-testid="channels-list" className="flex flex-col gap-2">
          {channels?.map((channel) => (
            <a
              key={channel.id}
              data-testid="channel-link"
              data-channel-id={channel.id}
              href={`/channel/${channel.id}`}
              className="rounded bg-neutral-100 px-4 py-2 hover:bg-neutral-200"
            >
              {channel.name}
            </a>
          ))}
          {channels?.length === 0 && (
            <p className="text-neutral-500">No channels yet. Create one!</p>
          )}
        </div>
      </div>

      <button
        data-testid="logout-btn"
        onClick={logout}
        className="rounded bg-red-600 px-4 py-2 text-white hover:bg-red-700"
      >
        Logout
      </button>
    </div>
  );
};

import { type AuthUser } from "wasp/auth";
import { useQuery } from "wasp/client/operations";
import { getChannel, getChannelMessages, type MessageWithSender } from "../queries";
import { createMessage, markAsRead } from "../actions";
import { useParams } from "react-router";
import { useSocket, type ServerToClientEvents, type ClientToServerEvents } from "wasp/client/webSocket";
import { useState, useEffect, useRef, useCallback } from "react";

export const ChannelPage = ({ user }: { user: AuthUser }) => {
  const { id } = useParams<{ id: string }>();
  const channelId = parseInt(id ?? "0");

  const { data: channel, isLoading: channelLoading } = useQuery(getChannel, {
    id: channelId,
  });
  const { data: messages, isLoading: messagesLoading, refetch } = useQuery(
    getChannelMessages,
    { channelId },
  );

  const [messageInput, setMessageInput] = useState("");
  const [activeUsers, setActiveUsers] = useState<string[]>([]);
  const [typingUsers, setTypingUsers] = useState<Map<string, number>>(new Map());
  const typingTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const typingTimersRef = useRef<Map<string, ReturnType<typeof setTimeout>>>(
    new Map(),
  );

  const { socket } = useSocket<ServerToClientEvents, ClientToServerEvents>();

  // Join channel on mount, leave on unmount
  useEffect(() => {
    if (!socket) return;

    socket.emit("joinChannel", { channelId });

    // Active users handler
    const handleActiveUsers = (usernames: string[]) => {
      setActiveUsers(usernames);
    };

    // Typing handler
    const handleTyping = ({
      username,
      isTyping,
    }: {
      username: string;
      isTyping: boolean;
    }) => {
      setTypingUsers((prev) => {
        const next = new Map(prev);
        if (isTyping) {
          next.set(username, Date.now());
          // Clear existing timer for this user
          const existingTimer = typingTimersRef.current.get(username);
          if (existingTimer) {
            clearTimeout(existingTimer);
          }
          // Set 3-second timeout to clear typing indicator
          const timer = setTimeout(() => {
            setTypingUsers((current) => {
              const updated = new Map(current);
              updated.delete(username);
              return updated;
            });
            typingTimersRef.current.delete(username);
          }, 3000);
          typingTimersRef.current.set(username, timer);
        } else {
          next.delete(username);
          const existingTimer = typingTimersRef.current.get(username);
          if (existingTimer) {
            clearTimeout(existingTimer);
            typingTimersRef.current.delete(username);
          }
        }
        return next;
      });
    };

    // New message handler
    const handleMessageCreated = () => {
      refetch();
      // Clear typing for the sender (they sent a message)
      setTypingUsers((prev) => {
        const next = new Map(prev);
        // We don't know who sent it here, but the typing event with isTyping:false
        // will handle it
        return next;
      });
    };

    // Read receipt updated handler
    const handleReadReceiptUpdated = () => {
      refetch();
    };

    socket.on("activeUsers", handleActiveUsers);
    socket.on("typing", handleTyping);
    socket.on("messageCreated", handleMessageCreated);
    socket.on("readReceiptUpdated", handleReadReceiptUpdated);

    return () => {
      socket.emit("leaveChannel", { channelId });
      socket.off("activeUsers", handleActiveUsers);
      socket.off("typing", handleTyping);
      socket.off("messageCreated", handleMessageCreated);
      socket.off("readReceiptUpdated", handleReadReceiptUpdated);
      // Clear all typing timers
      for (const timer of typingTimersRef.current.values()) {
        clearTimeout(timer);
      }
      typingTimersRef.current.clear();
    };
  }, [socket, channelId, refetch]);

  // Mark messages as read when messages change
  useEffect(() => {
    if (!messages || messages.length === 0) return;
    const lastMessage = messages[messages.length - 1];
    markAsRead({
      channelId,
      lastReadMessageId: lastMessage.id,
    }).catch(() => {});
  }, [messages, channelId]);

  const sendTyping = useCallback(
    (isTyping: boolean) => {
      if (!socket) return;
      socket.emit("typing", { channelId, isTyping });
    },
    [socket, channelId],
  );

  const handleKeyDown = (_e: React.KeyboardEvent<HTMLInputElement>) => {
    // Send typing:true
    sendTyping(true);

    // Reset the local typing timeout
    if (typingTimeoutRef.current) {
      clearTimeout(typingTimeoutRef.current);
    }
    typingTimeoutRef.current = setTimeout(() => {
      sendTyping(false);
    }, 3000);
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!messageInput.trim()) return;

    try {
      await createMessage({ channelId, content: messageInput.trim() });
      setMessageInput("");
      // Clear typing indicator immediately
      sendTyping(false);
      if (typingTimeoutRef.current) {
        clearTimeout(typingTimeoutRef.current);
        typingTimeoutRef.current = null;
      }
      refetch();
    } catch {
      // ignore
    }
  };

  if (channelLoading) {
    return (
      <div className="flex justify-center p-12">
        <p>Loading channel...</p>
      </div>
    );
  }

  if (!channel) {
    return (
      <div className="flex justify-center p-12">
        <p>Channel not found</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col items-center gap-4 px-8 py-6">
      <h1 data-testid="channel-title" className="text-3xl font-bold">
        {channel.name}
      </h1>

      {/* Active Users */}
      <div className="w-full max-w-3xl">
        <div data-testid="active-users-list" className="flex flex-wrap gap-2">
          {activeUsers.map((username) => (
            <span
              key={username}
              data-testid="active-user-item"
              data-username={username}
              className="rounded-full bg-green-100 px-3 py-1 text-sm text-green-800"
            >
              {username}
            </span>
          ))}
        </div>
      </div>

      {/* Typing Indicators */}
      <div className="w-full max-w-3xl">
        <div data-testid="typing-indicators" className="flex flex-wrap gap-1">
          {Array.from(typingUsers.keys()).map((username) => (
            <span
              key={username}
              data-testid="typing-user-item"
              data-username={username}
              className="text-sm italic text-neutral-500"
            >
              {username} is typing...
            </span>
          ))}
        </div>
      </div>

      {/* Messages */}
      <div className="w-full max-w-3xl">
        {messagesLoading && <p>Loading messages...</p>}
        <div
          data-testid="messages-list"
          className="flex flex-col gap-3"
        >
          {messages?.map((message) => {
            // Determine who has read this message
            const readers = message.readReceipts.filter(
              (rr) =>
                rr.lastReadMessageId >= message.id &&
                rr.userId !== message.senderId,
            );

            return (
              <div
                key={message.id}
                data-testid="message-item"
                data-message-id={message.id}
                className="rounded bg-white p-3 shadow-sm"
              >
                <div className="flex items-baseline gap-2">
                  <span
                    data-testid="message-sender"
                    className="font-semibold text-blue-600"
                  >
                    {message.sender?.username ?? "Unknown"}
                  </span>
                  <span className="text-xs text-neutral-400">
                    {new Date(message.createdAt).toLocaleTimeString()}
                  </span>
                </div>
                <p
                  data-testid="message-content"
                  className="mt-1 text-neutral-800"
                >
                  {message.content}
                </p>
                <div
                  data-testid="message-read-receipts"
                  className="mt-1 flex flex-wrap gap-1"
                >
                  {readers.map((rr) => (
                    <span
                      key={rr.id}
                      data-testid="reader-name"
                      data-username={rr.user.username}
                      className="text-xs text-neutral-400"
                    >
                      {rr.user.username}
                    </span>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Message Input */}
      <div className="w-full max-w-3xl">
        <form
          onSubmit={handleSendMessage}
          className="flex gap-2"
        >
          <input
            id="message-input"
            data-testid="message-input"
            type="text"
            value={messageInput}
            onChange={(e) => setMessageInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Type a message..."
            className="flex-1 rounded border border-neutral-300 px-3 py-2"
          />
          <button
            id="send-message-btn"
            data-testid="send-message-btn"
            type="submit"
            className="rounded bg-blue-600 px-4 py-2 text-white hover:bg-blue-700"
          >
            Send
          </button>
        </form>
      </div>

      <a
        data-testid="back-to-channels"
        href="/"
        className="text-blue-600 underline hover:text-blue-800"
      >
        Back to Channels
      </a>
    </div>
  );
};

